return {api_version=1,id="EX1_132",name="Eye for an Eye",text="<b>Secret:</b> When your hero takes damage, deal that much damage to the enemy hero.",set="EXPERT1",type="spell",class="paladin",rarity="common",spell_school="holy",cost=1,keywords={"secret"},triggers={{event="damaged",timing="after",active_zones={"secret"},condition=function(ctx,self,e)return e.target==ctx:player(ctx:controller(self)).hero and e.amount>0 end,effect=function(ctx,self,e)ctx:reveal_secret(self);local enemy=ctx:opponent(ctx:controller(self));cardlib.effects.damage_ignoring_spell_damage(ctx, ctx:player(enemy).hero,e.amount)end}}}
